/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: titledReview, mount, group, item
 * Tests
 *   - the count follows the draft as edited, proposals and unsaved edits included, and a group is mixed while only some of its items are selected
 *   - a held item is a disabled box with its reason, and members the selected numbers would leave at one position are named
 *   - choices survive a save: a deselected proposal stays deselected and unsaved, and the saved proposals stay selected
 *   - a stored number that disagreed with its title, corrected and saved, lets the proposal the table shows arrive selected, its cleaned titles too
 *   - a review captured for lookup
 *     - it lists every change with its default: review-only items and lookup-filled values selected, a conflict held, the member line and the identities it owns
 *     - a member line lists removed Credits
 *     - an identity still needing a record is marked and named, with a link to the identity rows
 *     - when the Album's primary Artists change, it says Album Credits are never copied and names the tracks still crediting a replaced Artist
 * @end-catalog */

import { useState } from 'react';
import { act, cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import type { CatalogReview, ReviewDraft } from './catalogReviewApi';
import { memberKey, reviewApplyModel, type ApplyChoice } from './catalogReviewApplyModel';
import type { ReviewEditorDerived, ReviewEdits } from './catalogReviewEdits';
import { capturedCatalogReview, catalogReview, reviewJson, session, slotId, slotTwo, viewer } from './catalogReviewFixtures.testSupport';
import { guestHandle, leadHandle, reviewAfterLookup, reviewIdentityResponse, reviewLookupResponse } from './catalogReviewLookupFixtures.testSupport';
import type { ReviewIdentityResponse, ReviewLookupResponse } from './catalogReviewLookupApi';
import { reviewEditor } from './catalogReviewProposal';
import { CatalogReviewRange } from './CatalogReviewRange';

/**
 * The review page's update range, without the page: its count follows the draft as edited (unsaved edits and proposals included),
 * a group's checkbox is mixed while only some of its items are selected, a held item is a disabled box with its reason, members
 * the selected numbers would leave at one position are named, and choices survive a save. The review is not captured for lookup,
 * so the range reads nothing. Every name is synthetic.
 */

beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); });

/** A review whose captured titles give Disc and Track Numbers: the first member stores Track Number 1, the rest are empty. */
function titledReview(): CatalogReview {
  const item = catalogReview(), titles = ['1-01 Synthetic first', '1-02 Synthetic second'];
  return { ...item, suggestions: [], source: { ...item.source, tracks: item.source.tracks.map((track, index) => ({ ...track, title: titles[index] })) },
    draft: { ...item.draft, tracks: item.draft.tracks.map((track, index) => ({ ...track, title: titles[index] })) } };
}
/** Mounts the range with the page's state: the saved review, the edits and the choices, the proposal table's view derived from them. */
function mount(first: CatalogReview, edits: ReviewEdits = {}) {
  const derived = vi.fn<(value: ReviewEditorDerived) => void>(), client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  let save: (draft: ReviewDraft) => void = () => undefined;
  function Harness() {
    const [state, setState] = useState({ item: first, edits }), [choices, setChoices] = useState<Record<string, ApplyChoice>>({});
    const view = reviewEditor(state.item.source, state.item.draft, state.edits);
    // A save stores the draft the range derived and starts a new edit over it, keeping the choices.
    save = draft => setState({ item: { ...state.item, revision: state.item.revision + 1, draft }, edits: {} });
    return <CatalogReviewRange item={state.item} base={state.item.draft} edits={state.edits} view={{ ...view, base: state.item.draft, edits: state.edits }} choices={choices}
      disabled={false} onChoose={next => setChoices(previous => ({ ...previous, ...next }))} onDerived={derived} />;
  }
  render(<QueryClientProvider client={client}><Harness /></QueryClientProvider>);
  const range = () => screen.getByText(/^This update ·/).closest('details')!;
  return { derived, range, save: () => act(() => save(derived.mock.lastCall![0].draft)),
    open: () => { range().open = true; for (const fold of range().querySelectorAll('details')) fold.open = true; } };
}
const group = (name: string) => within(screen.getByRole('region', { name })).getAllByRole('checkbox')[0] as HTMLInputElement;
const item = (name: RegExp) => screen.getByRole('checkbox', { name }) as HTMLInputElement;

test('the count follows the draft as edited, proposals and unsaved edits included, and a group is mixed while only some of its items are selected', () => {
  const { range, derived, open } = mount(titledReview(), { album: { title: 'An unsaved synthetic title' } });
  // Three proposed numbers fill empty values and are selected; the edited Album title replaces a stored one and is not.
  expect(range().querySelector('summary')).toHaveTextContent('This update · 3 selected · Adjust the range');
  open();
  const numbers = group('Disc and Track Numbers');
  expect([numbers.checked, numbers.indeterminate]).toEqual([true, false]);
  expect(within(screen.getByRole('region', { name: 'Disc and Track Numbers' })).getByText('3 of 3 selected')).toBeVisible();
  const title = item(/^Title · Synthetic catalog Album/);
  expect(title).not.toBeChecked();
  expect(title.closest('label')).toHaveTextContent('Replaces Synthetic catalog Album → An unsaved synthetic title');
  expect(title.closest('label')!.querySelector('s')).toHaveTextContent('Synthetic catalog Album');
  expect(item(/^Disc number · 1-02 Synthetic second/).closest('label')).toHaveTextContent('Fills 1');
  // Deselecting one number mixes its group and lowers the count; ticking the group selects them all again.
  fireEvent.click(item(/^Disc number · 1-02 Synthetic second/));
  expect([numbers.checked, numbers.indeterminate]).toEqual([false, true]);
  expect(range().querySelector('summary')).toHaveTextContent('This update · 2 selected');
  // The draft a save writes carries the selected proposals and the edits only.
  expect(derived.mock.lastCall![0].draft.tracks.map(track => [track.discNumber, track.trackNumber])).toEqual([[1, 1], [null, 2]]);
  expect(derived.mock.lastCall![0].draft.album.title).toBe('An unsaved synthetic title');
  expect(derived.mock.lastCall![0].count).toBe(2);
  fireEvent.click(numbers);
  expect([numbers.checked, numbers.indeterminate]).toEqual([true, false]);
  expect(range().querySelector('summary')).toHaveTextContent('This update · 3 selected');
  // Selecting the Album title counts it too.
  fireEvent.click(group('Album title'));
  expect(range().querySelector('summary')).toHaveTextContent('This update · 4 selected');
});

test('a held item is a disabled box with its reason, and members the selected numbers would leave at one position are named', () => {
  const item0 = titledReview(), cleaned = { tracks: { [slotTwo]: { title: 'Synthetic second' } } };
  const { open } = mount(item0, cleaned);
  open();
  // The cleaned title arrives selected, as turning the cleanup on chooses it.
  const title = item(/^Title · 1-02 Synthetic second/);
  expect(title).toBeChecked();
  // Without its member's Disc and Track Number it cannot apply, and says so in text.
  fireEvent.click(item(/^Track number · 1-02 Synthetic second/));
  expect(title).toBeDisabled();
  expect(title).not.toBeChecked();
  expect(title).toHaveAccessibleDescription('Applies only with this track\'s Disc and Track Number');
  const titles = group('Track titles · 1 track');
  expect(titles).toBeDisabled();
  fireEvent.click(item(/^Track number · 1-02 Synthetic second/));
  expect(title).toBeEnabled();
  expect(title).toBeChecked();
  cleanup();
  // A typed number another member already has: unselected as a manual value, and named once it is selected.
  const { open: openAgain } = mount(titledReview(), { tracks: { [slotTwo]: { trackNumber: 1 } } });
  openAgain();
  expect(screen.queryByText(/would share one Disc and Track Number/)).not.toBeInTheDocument();
  const typed = item(/^Track number · 1-02 Synthetic second/);
  expect(typed).not.toBeChecked();
  fireEvent.click(typed);
  expect(screen.getByText('These tracks would share one Disc and Track Number: 1 · 1-01 Synthetic first, 2 · 1-02 Synthetic second')).toBeVisible();
});

test('choices survive a save: a deselected proposal stays deselected and unsaved, and the saved proposals stay selected', () => {
  const { range, derived, save, open } = mount(titledReview());
  open();
  fireEvent.click(item(/^Disc number · 1-02 Synthetic second/));
  expect(range().querySelector('summary')).toHaveTextContent('This update · 2 selected');
  save();
  // The save stored the selected proposals only; the deselected one is still a proposal, still deselected.
  expect(derived.mock.lastCall![0].base.tracks.map(track => [track.discNumber, track.trackNumber])).toEqual([[1, 1], [null, 2]]);
  open();
  expect(range().querySelector('summary')).toHaveTextContent('This update · 2 selected');
  expect(item(/^Disc number · 1-02 Synthetic second/)).not.toBeChecked();
  expect(item(/^Disc number · 1-01 Synthetic first/)).toBeChecked();
  expect(item(/^Track number · 1-02 Synthetic second/)).toBeChecked();
  expect(derived.mock.lastCall![0].draft.tracks.find(track => track.slotId === slotTwo)!.discNumber).toBeNull();
  expect(derived.mock.lastCall![0].draft.tracks.find(track => track.slotId === slotId)!.discNumber).toBe(1);
});

test('a stored number that disagreed with its title, corrected and saved, lets the proposal the table shows arrive selected, its cleaned titles too', () => {
  const corrected = titledReview(); corrected.source.tracks[1].trackNumber = 7; corrected.draft.tracks[1].trackNumber = 2;
  const { range, open } = mount(corrected, { tracks: { [slotId]: { title: 'Synthetic first' }, [slotTwo]: { title: 'Synthetic second' } } });
  open();
  expect(item(/^Disc number · 1-01 Synthetic first/)).toBeChecked();
  expect(item(/^Disc number · 1-02 Synthetic second/)).toBeChecked();
  // The corrected number replaces the stored 7, so it stays the administrator's choice.
  expect(item(/^Track number · 1-02 Synthetic second/)).not.toBeChecked();
  expect(item(/^Title · 1-01 Synthetic first/)).toBeChecked();
  expect(item(/^Title · 1-02 Synthetic second/)).toBeChecked();
  expect(range().querySelector('summary')).toHaveTextContent('This update · 4 selected');
});

describe('a review captured for lookup', () => {
  /** The looked-up review with the guest answered, so nothing waits, and its lookup and identity reads. */
  function lookedUp() {
    const item = reviewAfterLookup(capturedCatalogReview()), identity = reviewIdentityResponse();
    identity.identities[0] = { ...identity.identities[0], needsAnswer: false, decision: { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', boundMusicBrainzId: null,
      action: 'create-distinct', candidateId: null, candidateRevision: null } };
    return { item, identity, lookup: reviewLookupResponse() };
  }
  /** Mounts the range on `item` with no edits, answering its lookup and identity reads; returns the choices it reported. */
  async function mountRead(item: CatalogReview, lookup: ReviewLookupResponse, identity: ReviewIdentityResponse) {
    vi.stubGlobal('fetch', vi.fn(async (path: string) => reviewJson(path.endsWith('/lookup') ? lookup : identity)));
    const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }), onChoose = vi.fn();
    client.setQueryData(['browser-session'], session);
    render(<QueryClientProvider client={client}><CatalogReviewRange item={item} base={item.draft} edits={{}} view={null} choices={{}} disabled={false} onChoose={onChoose}
      onDerived={() => undefined} /></QueryClientProvider>);
    await screen.findByRole('checkbox', { name: /^Artists · Synthetic second track/ });
    return onChoose;
  }
  afterEach(() => vi.unstubAllGlobals());

  test('it lists every change with its default: review-only items and lookup-filled values selected, a conflict held, the member line and the identities it owns', async () => {
    const { item: review, identity, lookup } = lookedUp();
    identity.identities[1] = { ...identity.identities[1], musicBrainzIdWrite: { scope: 'artist', identity: leadHandle, musicBrainzId: '00000000-0000-4000-8000-0000000000a1', replaces: null } };
    identity.musicBrainzIds = [identity.identities[1].musicBrainzIdWrite!];
    const onChoose = await mountRead(review, lookup, identity);
    expect(screen.getByText(/^This update · 4 selected/)).toBeInTheDocument();
    for (const name of [/^Artists · Synthetic catalog Album/, /^Expected tracklist · Synthetic catalog Album/, /^Track number · Synthetic second track/, /^Artists · Synthetic second track/])
      expect(item(name)).toBeChecked();
    const date = item(/^Release date · Synthetic catalog Album/);
    expect([date.checked, date.disabled]).toEqual([false, true]);
    expect(date).toHaveAccessibleDescription('Answer its lookup conflict first');
    // The member stored as Unknown gains its own track's artist and becomes documented.
    expect(await screen.findByText('This track\'s Artist credits will be marked Documented (currently Unknown).')).toBeInTheDocument();
    const lines = within((await screen.findByRole('heading', { name: 'Artists and label' })).closest('section')!);
    expect(lines.getByText('Reuses the existing Synthetic catalog Artist · Visibility: Hidden')).toBeInTheDocument();
    expect(lines.getByText('Records MusicBrainz ID 00000000-0000-4000-8000-0000000000a1')).toBeInTheDocument();
    expect(lines.getByText('Creates Synthetic guest as new')).toBeInTheDocument();
    fireEvent.click(item(/^Artists · Synthetic second track/));
    expect(onChoose).toHaveBeenCalledWith({ [memberKey(slotTwo)]: { checked: false, basis: JSON.stringify(review.draft.tracks[1].artists) } });
  });

  test('a member line lists removed Credits', async () => {
    const { item, identity, lookup } = lookedUp(), old = { creditId: 'synthetic_old_credit', subjectType: 'artist' as const, subjectId: '151515151515151515151515', identity: null,
      name: 'Synthetic old Artist', role: 'primary' as const, joinPhrase: null };
    identity.members[0] = { ...identity.members[0], current: [old], removedCreditIds: [old.creditId], attribution: null };
    await mountRead(item, lookup, identity);
    expect(await screen.findByText('Credits removed: Synthetic old Artist')).toBeInTheDocument();
  });

  test('an identity still needing a record is marked and named, with a link to the identity rows', async () => {
    const { item, lookup } = lookedUp(), identity = reviewIdentityResponse();
    vi.stubGlobal('fetch', vi.fn(async (path: string) => reviewJson(path.endsWith('/lookup') ? lookup : identity)));
    const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
    // The guest's lists arrive unselected while it needs an answer; chosen, they bring its line in, which needs a decision.
    const albumArtists = reviewApplyModel({ item, lookup: lookup.lookup, summary: null, waiting: null, identity, choices: {} }).items.find(entry => entry.key === 'album::artists')!;
    render(<QueryClientProvider client={client}><CatalogReviewRange item={item} base={item.draft} edits={{}} view={null} choices={{ 'album::artists': { checked: true, basis: albumArtists.basis } }}
      disabled={false} onChoose={() => undefined} onDerived={() => undefined} /></QueryClientProvider>);
    const lines = within((await screen.findByRole('heading', { name: 'Artists and label' })).closest('section')!);
    expect(within(lines.getByText('Synthetic guest').closest('li')!).getByText('Needs a decision')).toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'Choose the records under Artists and label' })).toHaveAttribute('href', '#catalog-review-identities');
  });

  test('when the Album\'s primary Artists change, it says Album Credits are never copied and names the tracks still crediting a replaced Artist', async () => {
    const { item, identity, lookup } = lookedUp(), lead = identity.album!.current[0];
    identity.album = { ...identity.album!, next: [{ ...lead, creditId: null, subjectId: null, identity: guestHandle, name: 'Synthetic guest' }], replacedPrimaryArtistIds: [lead.subjectId!],
      membersNamingReplaced: [slotId] };
    await mountRead(item, lookup, identity);
    expect(await screen.findByText('Album Credits are never copied to tracks: each track\'s Artists change only from its own release track.')).toBeInTheDocument();
    expect(screen.getByText('Tracks that still credit an Artist the Album no longer credits: 1 · Synthetic first track')).toBeInTheDocument();
  });
});
